package com.clock.wallpaper;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import android.provider.Settings;import android.view.*;import android.widget.*;
public class PermissionActivity extends Activity { @Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(32,32,32,32);TextView t=new TextView(this);t.setText("Clock — отдельные разрешения\n\nЭтот экран не зависит от основных настроек Clock. Overlay нужен для показа поверх приложений, а специальные возможности — для покрытия системных панелей.");t.setTextSize(18);box.addView(t);Button go=new Button(this);go.setText("Открыть разрешение поверх приложений");go.setOnClickListener(v->{try{if(Build.VERSION.SDK_INT>=23)startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION, Uri.parse("package:"+getPackageName())));else startActivity(new Intent(Settings.ACTION_SETTINGS));}catch(Exception e){startActivity(new Intent(Settings.ACTION_MANAGE_APPLICATIONS_SETTINGS));}});box.addView(go);Button access=new Button(this);access.setText("Открыть специальные возможности");access.setOnClickListener(v->{try{startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS));}catch(Exception e){startActivity(new Intent(Settings.ACTION_SETTINGS));}});box.addView(access);TextView hint=new TextView(this);hint.setText("В специальных возможностях включите: Clock поверх системных панелей.");hint.setPadding(0,10,0,10);box.addView(hint);Button close=new Button(this);close.setText("Закрыть");close.setOnClickListener(v->finish());box.addView(close);setContentView(box);}}
